import{_ as i,l as o,o as a,c as d,v as l,p as n,x as r,d as s,i as c,S as m}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"可并堆","description":"","frontmatter":{"title":"可并堆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mergeable-heap.md","filePath":"cs/mergeable-heap.md","lastUpdated":1789023840000}'),p={name:"cs/mergeable-heap.md"};function h(_,e,u,f,k,b){const t=o("Mermaid");return a(),d("div",null,[e[1]||(e[1]=l('<h1 id="可并堆" tabindex="-1">可并堆 <a class="header-anchor" href="#可并堆" aria-label="Permalink to &quot;可并堆&quot;">​</a></h1><div class="epigraph"><p>优先队列加上 `meld`：两堆合成一堆，原堆作废；复杂度写在合同上，表示可以是左偏、二项或斐波那契。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein；Okasaki, Purely Functional Data Structures；Tarjan 摊还文献整理</footer></div><p><a href="/cs/leftist-pairing-heap">左偏与配对</a>、<a href="/cs/fibonacci-heap">斐波那契堆</a>、<a href="/cs/binomial-heap">二项堆</a> 已各给一种表示。调用方若绑死「必须完全二叉树数组」，<code>meld</code> 无法快。本课不重推 \\(B_k\\)。缺口是 ADT：可并堆的操作集与代价表，以及何时不要用可并堆。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准二叉堆：<a href="/cs/array-random-access">数组</a> 下标父子，\\(\\mathrm{insert}/\\mathrm{extract\\text{-}min}\\) 最坏 \\(O(\\log n)\\)，<code>meld</code> 要把一边插入另一边。可并堆合同至少含：<code>make</code>、<code>insert</code>、<code>find-min</code>、<code>extract-min</code>、<code>meld</code>；常加 <code>decrease-key</code>（需句柄）。缺口不是再发明第四种树，而是<strong>按使用模式选表示</strong>：只 meld 用左偏/二项；大量减键用 Fib（理论）或配对（实践）；不要在不可移动句柄的数组堆上假装 \\(O(\\log n)\\) meld。</p><p><span class="marginnote">Okasaki 给函数式可并堆（配对、斜堆）另一套摊还。本课偏命令式合同，函数式队列在后课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表（教学用，常数省略）：</p><ul><li>二叉堆：meld 慢，减键 \\(O(\\log n)\\)，局部性最好。</li><li>左偏：meld \\(O(\\log n)\\) 最坏，实现中等。</li><li>二项：meld \\(O(\\log n)\\)，形状清晰。</li><li>Fib：减键摊还 \\(O(1)\\)，extract-min \\(O(\\log n)\\) 摊还。</li><li>配对：meld/减键实践快，界依赖文献版本。</li></ul>',9)),(a(),n(m,null,{default:r(()=>[c(t,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADT%5B%22%E5%8F%AF%E5%B9%B6%E5%A0%86%20ADT%22%5D%20--%3E%20MELD%5B%22meld%22%5D%0A%20%20ADT%20--%3E%20DK%5B%22decrease-key%20%E5%8F%AF%E9%80%89%22%5D%0A%20%20MELD%20--%3E%20REP%5B%22%E5%B7%A6%E5%81%8F%20%2F%20%E4%BA%8C%E9%A1%B9%20%2F%20Fib%20%2F%20%E9%85%8D%E5%AF%B9%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<p>句柄：decrease-key 必须能找到节点。数组堆用下标；树用指针。meld 之后旧句柄属于新堆。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>算法课里 Kruskal 用并查集不靠可并堆；Dijkstra/Prim 的减键版本才关心堆合同。本课不重写那些算法，只要求选堆时看操作频率。函数式持久 meld 用路径复制，与命令式破坏性 meld 不同——后课持久化再分。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入软堆、或并行 meld 的 PRAM 结果。双端（同时要 max 与 min）不是 meld 的推论，下一课专门给双端优先队列。</p><p>后课默认：需要 meld 就换可并表示。既要最小也要最大，用双端堆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可并堆 = 优先队列 + meld；表示按操作选。</li><li>减键要句柄；数组二叉堆不适合快 meld。</li><li>双端优先队列是下一结构。</li><li>出处：Cormen et al.；Okasaki；Tarjan。</li></ul>',8))])}const E=i(p,[["render",h]]);export{T as __pageData,E as default};
